30	    /** 访客当日已占用额度；账目行不存在视为 0。 */
31	    public int getUsedVisitor(String campaignId, String visitorId, LocalDate utcDate) {
32	        Integer value = jdbc.query("SELECT used_visitor FROM quota_visitor_ledger "
33	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
34	                rs -> rs.next() ? rs.getInt(1) : null,
35	                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
36	        return value == null ? 0 : value;
37	    }
