    private void assert409(Runnable action) {
        var ex = assertThrows(com.example.starter.exposure.web.ApiException.class, action::run);
        assertEquals(409, ex.getStatus().value());
    }

    private void assert429(Runnable action) {
        var ex = assertThrows(com.example.starter.exposure.web.ApiException.class, action::run);
