package com.example.starter.exposure.domain;

/**
 * 缺额轮转选择池 PO。池成员与权重创建后固定，版本恒为 1。
 *
 * @param poolId       选择池编号，全局唯一
 * @param poolVersion  池版本号，当前恒为 1；选择请求可携带期望版本校验，不一致返回 409
 * @param createdBy    创建操作者
 * @param createdAtUtc 创建时刻（epoch 毫秒，UTC）
 */
public record Pool(
        String poolId,
        int poolVersion,
        String createdBy,
        long createdAtUtc
) {
}

package com.example.starter.exposure.domain;

/**
 * 选择池成员 PO。缺额（{@link #committedDeficit}）为精确整数，可正可负；
 * 仅在关联预占确认时正式提交，取消/到期不推进，跨 UTC 日不清零。
 *
 * @param poolId           所属选择池编号
 * @param campaignId       成员公告编号
 * @param weight           轮转权重，正整数 1～10
 * @param committedDeficit 已正式提交的缺额计数，初始 0
 */
public record PoolMember(
        String poolId,
        String campaignId,
        int weight,
        long committedDeficit
) {
}

package com.example.starter.exposure.domain;

/**
 * 池轮转选择记录 PO：一次选择对应一条曝光预占单，冻结选中公告身份，旧重放不重新选择。
 *
 * @param reservationId 关联的预占单编号
 * @param poolId        所属选择池编号
 * @param campaignId    选中的公告编号
 * @param visitorId     合成访客编号
 * @param createdAtUtc  选择时刻（epoch 毫秒，UTC）
 */
public record PoolSelection(
        String reservationId,
        String poolId,
        String campaignId,
        String visitorId,
        long createdAtUtc
) {
}

