            .map(member -> new PoolResponse.Member(
                    member.campaignId(), member.weight(), member.committedDeficit()))
            .toList();
    return new PoolResponse(pool.poolId(), pool.poolVersion(), members,
            activeReservationId, pool.createdAtUtc());
}

